'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';

export type SegmentedOption = {
  value: string;
  label: React.ReactNode;
  /** Optional leading icon. */
  icon?: React.ReactNode;
  disabled?: boolean;
};

export type SegmentedControlProps = Omit<React.HTMLAttributes<HTMLDivElement>, 'onChange'> & {
  /** Options rendered as segments. */
  options: SegmentedOption[];
  /** Controlled selected value. Use string[] when multiple. */
  value?: string | string[];
  /** Initial selection when uncontrolled. */
  defaultValue?: string | string[];
  /** Fires with the next selection. */
  onValueChange?: (value: string | string[]) => void;
  /** Allow more than one segment to be active. Default false. */
  multiple?: boolean;
  /** Control density. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  /** Stretch segments to fill the container width. */
  fullWidth?: boolean;
};

const sizeClasses = {
  sm: 'h-8 px-2.5 text-xs',
  md: 'h-9 px-3 text-sm',
  lg: 'h-10 px-4 text-sm',
} as const;

/**
 * Segmented control for switching a view or filter. Single-select uses radio
 * semantics and arrow-key navigation; multiple-select uses pressed buttons.
 * Use it for filters such as All / Investors / Advisors, not for tab panels
 * (use Tabs when each segment owns a tabpanel).
 */
export const SegmentedControl = React.forwardRef<HTMLDivElement, SegmentedControlProps>(
  function SegmentedControl(
    {
      options,
      value,
      defaultValue,
      onValueChange,
      multiple = false,
      size = 'md',
      fullWidth = false,
      className,
      'aria-label': ariaLabel = 'Segmented control',
      ...props
    },
    ref
  ) {
    const isControlled = value !== undefined;
    const [internal, setInternal] = React.useState<string | string[]>(() =>
      multiple
        ? Array.isArray(defaultValue)
          ? defaultValue
          : []
        : typeof defaultValue === 'string'
          ? defaultValue
          : ''
    );
    const current = isControlled ? value : internal;
    const selected = multiple
      ? Array.isArray(current)
        ? current
        : []
      : typeof current === 'string'
        ? current
        : '';

    const refs = React.useRef<Array<HTMLButtonElement | null>>([]);

    const commit = (next: string | string[]) => {
      if (!isControlled) setInternal(next);
      onValueChange?.(next);
    };

    const select = (option: SegmentedOption) => {
      if (option.disabled) return;
      if (multiple) {
        const currentValues = Array.isArray(selected) ? selected : [];
        commit(
          currentValues.includes(option.value)
            ? currentValues.filter((entry) => entry !== option.value)
            : [...currentValues, option.value]
        );
      } else {
        commit(option.value);
      }
    };

    const moveFocus = (direction: 1 | -1 | 'first' | 'last') => {
      if (multiple) return;
      const enabled = options
        .map((option, index) => ({ option, index }))
        .filter(({ option }) => !option.disabled);
      if (enabled.length === 0) return;
      const activeValue = typeof selected === 'string' ? selected : '';
      const currentIndex = enabled.findIndex(({ option }) => option.value === activeValue);
      let nextIndex: number;
      if (direction === 'first') nextIndex = 0;
      else if (direction === 'last') nextIndex = enabled.length - 1;
      else {
        const from = currentIndex === -1 ? 0 : currentIndex;
        nextIndex = (from + direction + enabled.length) % enabled.length;
      }
      const next = enabled[nextIndex];
      if (!next) return;
      commit(next.option.value);
      refs.current[next.index]?.focus();
    };

    const onKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (multiple) return;
      if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
        event.preventDefault();
        moveFocus(1);
      } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
        event.preventDefault();
        moveFocus(-1);
      } else if (event.key === 'Home') {
        event.preventDefault();
        moveFocus('first');
      } else if (event.key === 'End') {
        event.preventDefault();
        moveFocus('last');
      }
    };

    return (
      <div
        ref={ref}
        role={multiple ? 'group' : 'radiogroup'}
        aria-label={ariaLabel}
        className={cn(
          'inline-flex items-center gap-1 rounded-lg border border-border bg-muted p-1',
          fullWidth && 'flex w-full',
          className
        )}
        {...props}
      >
        {options.map((option, index) => {
          const active = multiple
            ? Array.isArray(selected) && selected.includes(option.value)
            : selected === option.value;
          const firstEnabled = options.findIndex((entry) => !entry.disabled);
          const focusable = multiple || active || (!selected && index === firstEnabled);

          return (
            <button
              key={option.value}
              ref={(node) => {
                refs.current[index] = node;
              }}
              type="button"
              role={multiple ? undefined : 'radio'}
              aria-checked={multiple ? undefined : active}
              aria-pressed={multiple ? active : undefined}
              disabled={option.disabled}
              tabIndex={focusable ? 0 : -1}
              onClick={() => select(option)}
              onKeyDown={onKeyDown}
              className={cn(
                'inline-flex items-center justify-center gap-2 rounded-md font-medium transition-colors',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
                'disabled:pointer-events-none disabled:opacity-50',
                sizeClasses[size],
                fullWidth && 'flex-1',
                active
                  ? 'bg-background text-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground'
              )}
            >
              {option.icon && <span className="shrink-0 [&_svg]:size-4">{option.icon}</span>}
              <span className="truncate">{option.label}</span>
            </button>
          );
        })}
      </div>
    );
  }
);

{
  "id": "segmented-control",
  "name": "SegmentedControl",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.0",
  "sourceDir": "segmented-control",
  "exportName": "SegmentedControl",
  "description": "Single- or multi-select segmented control for view and filter switches.",
  "designIntent": "Filters such as All / Investors / Advisors are often built with Tabs, which wrongly promises tabpanels. SegmentedControl provides radio semantics for single choice and pressed buttons for multi-select, with arrow-key navigation.",
  "props": [
    {
      "name": "options",
      "type": "SegmentedOption[]",
      "required": true,
      "description": "Segments to render: value, label, optional icon and disabled."
    },
    {
      "name": "value",
      "type": "string | string[]",
      "required": false,
      "description": "Controlled selection. Use string[] when multiple."
    },
    {
      "name": "defaultValue",
      "type": "string | string[]",
      "required": false,
      "description": "Initial selection when uncontrolled."
    },
    {
      "name": "onValueChange",
      "type": "(value: string | string[]) => void",
      "required": false,
      "description": "Fires with the next selection."
    },
    {
      "name": "multiple",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Allow more than one segment to be active."
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "required": false,
      "defaultValue": "md",
      "enum": [
        "sm",
        "md",
        "lg"
      ],
      "description": "Control density."
    },
    {
      "name": "fullWidth",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Stretch segments to fill the container width."
    }
  ],
  "examples": [
    {
      "title": "Single-select audience filter",
      "code": "<SegmentedControl\n  aria-label=\"Audience\"\n  value={audience}\n  onValueChange={setAudience}\n  options={[\n    { value: 'investors', label: 'Investors' },\n    { value: 'advisors', label: 'Advisors' },\n    { value: 'owners', label: 'Owners' },\n  ]}\n/>",
      "description": "Radio semantics with arrow-key navigation."
    },
    {
      "title": "Multi-select filter",
      "code": "<SegmentedControl\n  aria-label=\"Deal type\"\n  multiple\n  defaultValue={['m&a']}\n  options={[\n    { value: 'm&a', label: 'M&A' },\n    { value: 'debt', label: 'Debt' },\n  ]}\n/>",
      "description": "Pressed buttons for independent filters."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use it for tab panels",
      "explanation": "If each segment reveals its own panel, use Tabs so aria-controls and tabpanel semantics are correct.",
      "example": "// Avoid\n<SegmentedControl options={panels} />\n\n// Prefer\n<Tabs defaultValue=\"overview\">...</Tabs>"
    },
    {
      "title": "Don't omit the accessible name",
      "explanation": "A radiogroup without a name is ambiguous. Pass aria-label or aria-labelledby.",
      "example": "<SegmentedControl aria-label=\"Audience\" options={options} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Single-select semantics",
      "implementation": "Uses role=radiogroup and role=radio with aria-checked and roving tabindex",
      "userRequirements": "Provide an accessible name with aria-label or aria-labelledby"
    },
    {
      "feature": "Keyboard",
      "implementation": "Arrow keys move selection; Home and End jump to the first and last enabled segment",
      "userRequirements": "Keep labels short enough to scan"
    },
    {
      "feature": "Multi-select semantics",
      "implementation": "Uses role=group with aria-pressed on each segment",
      "userRequirements": "Use multiple only when choices are independent"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Segment labels",
      "guidelines": [
        "One or two words",
        "Parallel grammar",
        "No punctuation"
      ],
      "goodExamples": [
        "Investors",
        "Advisors",
        "Owners"
      ],
      "badExamples": [
        "Show me investors",
        "Advisors!"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "FilterChips",
      "relationship": "Pair a multi-select control with FilterChips to show and remove active filters",
      "example": "<><SegmentedControl multiple /><FilterChips filters={chips} /></>"
    },
    {
      "component": "Tabs",
      "relationship": "Use Tabs when each option owns a tabpanel; use SegmentedControl for filters",
      "example": "<Tabs defaultValue=\"overview\">...</Tabs>"
    }
  ],
  "relatedComponents": [
    "Tabs",
    "FilterChips",
    "SelectMenu"
  ]
}
